            'total_paid_tax_incl',
            'total_paid_tax_excl',
            'total_paid_real',
        ];

        /* Prevent from floating precision issues */
        foreach ($fieldsFloatType as $field) {
            if ($this->{$field} < 0) {
                $this->{$field} = 0;
            }

            $this->{$field} = (float) number_format($this->{$field}, Context::getContext()->getComputingPrecision(), '.', '');
        }

        /* Update order detail */
        $order_detail->product_quantity -= (int) $quantity;
        if ($order_detail->product_quantity == 0) {
            if (!$order_detail->delete()) {
                return false;
            }
            if (count($this->getProductsDetail()) == 0) {
                $history = new OrderHistory();
                $history->id_order = (int) $this->id;
                $history->changeIdOrderState(
                    (int) Configuration::get('PS_OS_CANCELED'),
